import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.CAUU6m5Y.js";const u=JSON.parse('{"title":"Gaps & Roadmap Improvements","description":"","frontmatter":{},"headers":[],"relativePath":"10-gaps-and-improvements.md","filePath":"10-gaps-and-improvements.md"}'),i={name:"10-gaps-and-improvements.md"};function n(s,e,l,c,d,p){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="gaps-roadmap-improvements" tabindex="-1">Gaps &amp; Roadmap Improvements <a class="header-anchor" href="#gaps-roadmap-improvements" aria-label="Permalink to &quot;Gaps &amp; Roadmap Improvements&quot;">​</a></h1><p>This document lists architectural improvements ranked by priority for future production iterations.</p><hr><h2 id="priority-0-critical-for-multi-node-production" tabindex="-1">Priority 0: Critical for Multi-Node Production <a class="header-anchor" href="#priority-0-critical-for-multi-node-production" aria-label="Permalink to &quot;Priority 0: Critical for Multi-Node Production&quot;">​</a></h2><ol><li><strong>Distributed Redis Queue for Waiting Room</strong>: Currently <code>WaitingRoomManager</code> holds queue tickets in local process RAM. In a multi-node deployment, moving queue state to Redis Sorted Sets (<code>ZADD</code> / <code>ZRANGE</code>) will allow horizontal scaling across 20+ FastAPI nodes.</li><li><strong>Asynchronous Payment Message Broker</strong>: Direct synchronous calls to external payment gateways create latency bottlenecks. Integrating Apache Kafka or AWS SQS will decouple order placement from payment capture.</li></ol><hr><h2 id="priority-1-high-operational-value" tabindex="-1">Priority 1: High Operational Value <a class="header-anchor" href="#priority-1-high-operational-value" aria-label="Permalink to &quot;Priority 1: High Operational Value&quot;">​</a></h2><ol start="3"><li><strong>Server-Sent Events (SSE) / WebSocket Push</strong>: Replace the 3-second client polling in <code>frontend/src/app.js</code> with SSE streams, reducing unnecessary HTTP request overhead on the <code>/dashboard/stock</code> endpoint.</li><li><strong>Automated Deadlock Detection &amp; Backoff</strong>: Add automated circuit breakers around Postgres query retries if lock wait timeouts exceed 500ms.</li></ol><hr><h2 id="priority-2-security-polish" tabindex="-1">Priority 2: Security &amp; Polish <a class="header-anchor" href="#priority-2-security-polish" aria-label="Permalink to &quot;Priority 2: Security &amp; Polish&quot;">​</a></h2><ol start="5"><li><strong>Hardware Security Fingerprinting</strong>: Enhance anti-scalper scoring with client-side WebAssembly hardware fingerprinting.</li><li><strong>Multi-Region Active-Passive Database Replication</strong>: Set up automated cross-region read replicas with automated failover.</li></ol>',11)])])}const h=t(i,[["render",n]]);export{u as __pageData,h as default};
